style:
/* 简青 —— 线条图标配蓝色标题，日期、单位、专业压成一行 */

.tw-jianqing.layout-profile.resume-paper .paper-header {
  margin-bottom: 7mm;
  padding-bottom: 4.6mm;
  border-bottom: 0.28mm solid #d9e4ea;
}

.tw-jianqing.layout-profile.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 8mm;
}

.tw-jianqing.layout-profile.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-jianqing.layout-profile.resume-paper .paper-photo {
  order: 3;
  width: 22mm;
  height: 30mm;
  border: 0.4mm solid #dae4ea;
  border-radius: 0;
  box-shadow: none;
}

.tw-jianqing.layout-profile.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eff4f7;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-jianqing.layout-profile.resume-paper .paper-name {
  color: #1b2a33;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.15);
  letter-spacing: 0.1em;
}

.tw-jianqing.layout-profile.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #66787f;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-jianqing.layout-profile.resume-paper .paper-role {
  margin-top: 1.8mm;
  color: #2a3c46;
  font-size: calc(var(--paper-base-size) * 0.98);
  font-weight: 500;
  letter-spacing: 0.02em;
}

.tw-jianqing.layout-profile.resume-paper .paper-contacts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 8mm;
  margin-top: 3mm;
  color: #33454e;
  font-size: calc(var(--paper-base-size) * 0.87);
}

.tw-jianqing.layout-profile.resume-paper .paper-contact {
  display: flex;
  gap: 1.6mm;
}

.tw-jianqing.layout-profile.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-jianqing.layout-profile.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: #7f9099;
}

/* 标题：线条图标 + 蓝字 + 通栏细线 */
.tw-jianqing.layout-profile.resume-paper .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.2mm;
  margin-bottom: 3.2mm;
  padding-bottom: 1.4mm;
  border-bottom: 0.28mm solid color-mix(in srgb, var(--paper-accent) 42%, #fff);
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.06);
  letter-spacing: 0.1em;
}

.tw-jianqing.layout-profile.resume-paper .paper-section__icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 4.6mm;
  height: 4.6mm;
  border: none;
  background: none;
  border-radius: 0;
  color: var(--paper-accent);
  print-color-adjust: exact;
}

.tw-jianqing.layout-profile.resume-paper .paper-section__icon svg {
  width: 100%;
  height: 100%;
}

.tw-jianqing.layout-profile.resume-paper .paper-style-line .paper-section__title span::before {
  display: none;
}

.tw-jianqing.layout-profile.resume-paper .paper-section__body {
  color: #2f3f48;
}

/* 条目：每个子元素默认占满一行，只把日期、单位、专业交出来同行 */
.tw-jianqing.layout-profile.resume-paper .paper-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 6mm;
  row-gap: 0.8mm;
}

.tw-jianqing.layout-profile.resume-paper .paper-item > * {
  flex: 1 0 100%;
}

.tw-jianqing.layout-profile.resume-paper .paper-item > .paper-item-head {
  flex: 0 1 auto;
  justify-content: flex-start;
  gap: 6mm;
}

.tw-jianqing.layout-profile.resume-paper .paper-item-head .paper-item-title {
  order: 2;
}

.tw-jianqing.layout-profile.resume-paper .paper-item-period {
  order: 1;
  flex: 0 0 auto;
  width: 27mm;
  color: #6f818a;
  font-size: calc(var(--paper-base-size) * 0.86);
  white-space: nowrap;
}

.tw-jianqing.layout-profile.resume-paper .paper-item > .paper-item-sub {
  flex: 0 0 auto;
  margin-top: 0;
  margin-left: auto;
  color: #3f515a;
}

.tw-jianqing.layout-profile.resume-paper .paper-item-title {
  color: #1d2c35;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-jianqing.layout-profile.resume-paper .paper-item-sub span + span::before {
  content: "";
  margin-right: 6mm;
}

.tw-jianqing.layout-profile.resume-paper .paper-rich {
  margin-top: 0.8mm;
}

.tw-jianqing.layout-profile.resume-paper .paper-rich ul,
.tw-jianqing.layout-profile.resume-paper .paper-rich ol {
  margin-top: 0.6mm;
  padding-left: 0;
  list-style: none;
}

.tw-jianqing.layout-profile.resume-paper .paper-rich li {
  position: relative;
  margin: 0.7mm 0;
  padding-left: 3.4mm;
}

.tw-jianqing.layout-profile.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.72em;
  left: 0.2mm;
  width: 1mm;
  height: 1mm;
  border-radius: 50%;
  background: #93a5ae;
  print-color-adjust: exact;
}

.tw-jianqing.layout-profile.resume-paper .paper-note__tag {
  color: #1d2c35;
  font-weight: 600;
}

/* 主修课程回到正文读法：去掉胶囊边框与内边距 */
.tw-jianqing.layout-profile.resume-paper .paper-note__tag {
  display: inline;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
  color: #1d2c35;
  font-weight: 600;
  font-size: inherit;
}

.tw-jianqing.layout-profile.resume-paper .paper-note__tag::after {
  content: "：";
}

.tw-jianqing.layout-profile.resume-paper .paper-footer {
  border-top: 0.2mm solid #e1e9ed;
  color: #9dabb2;
}
